package com.mohymods.kingdomsmp.profession;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class LibraryMasterReferenceTest {
 @Test void collectionNeedsSixReadableDistinctSubjectsAndSnapshotsEveryAnnotation(){var text=new StringBuilder();for(var subject:new TreeSet<>(LibraryReferenceCollection.SUBJECTS))text.append("subject=").append(subject).append("\nAccurate readable notes about this accessible kingdom system and its current safety rules.\n");var hash=LibraryReferenceCollection.validateText(text.toString());assertEquals(64,hash.length());assertNotEquals(hash,LibraryReferenceCollection.validateText(text+"A changed note must invalidate an outstanding inspection.\n"));assertThrows(IllegalStateException.class,()->LibraryReferenceCollection.validateText(text+"subject=magic\nDuplicated chapter is not another subject.\n"));assertThrows(IllegalStateException.class,()->LibraryReferenceCollection.validateText(text.toString().replace("subject=magic","subject=unknown")));assertThrows(IllegalStateException.class,()->LibraryReferenceCollection.validateText("subject=kingdom\nShort text."));}
 @Test void newMasterExpeditionEvidenceCannotBeInferredFromOldJourneymanVisits(){var p=UUID.randomUUID();var metrics=Set.of(LibraryFieldGuide.METRIC,LibraryMasterFieldGuide.METRIC);var data=new ProfessionEvidence(Profession.LIBRARIAN,metrics);var dimension=LibraryMasterFieldGuide.DIMENSION;var biome="twilightforest:forest";data.record(p,ProfessionRank.JOURNEYMAN,LibraryFieldGuide.METRIC,1,LibraryFieldGuide.identity(dimension,biome));assertFalse(data.seen(p,LibraryMasterFieldGuide.METRIC,LibraryMasterFieldGuide.identity(dimension,biome)));data.record(p,ProfessionRank.MASTER,LibraryMasterFieldGuide.METRIC,1,LibraryMasterFieldGuide.identity(dimension,biome));var restored=ProfessionEvidence.load(data.save(),Profession.LIBRARIAN,metrics);assertTrue(restored.seen(p,LibraryFieldGuide.METRIC,LibraryFieldGuide.identity(dimension,biome)));assertTrue(restored.seen(p,LibraryMasterFieldGuide.METRIC,LibraryMasterFieldGuide.identity(dimension,biome)));assertEquals(1,restored.count(p,ProfessionRank.MASTER,LibraryMasterFieldGuide.METRIC));}
}
